package com.manas.metaplatform.typesystem.compiler;

import com.manas.metaplatform.typesystem.dsl.FieldDecl;
import com.manas.metaplatform.typesystem.dsl.TypeDecl;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Emits a typed Java model class and a typed Java client class for one {@link TypeDecl}.
 * Output is plain source text; {@code codegen.GenerateClients} is what writes it to
 * {@code generated-clients/java/}. Every generated class is thin: the model is a POJO whose
 * fields and getters/setters exactly mirror the declared fields, and the client's typed
 * methods (not just the {@code GeneratedTypeClient} interface methods) delegate to the one
 * hand-written {@link com.manas.metaplatform.typesystem.client.TypeClientSupport} for the
 * actual HTTP work, the same division of labor a real codegen tool uses between generated
 * per-type code and a shared runtime library.
 */
public final class JavaClientEmitter {

    public static final String MODEL_PACKAGE = "com.manas.metaplatform.generated.model";
    public static final String CLIENT_PACKAGE = "com.manas.metaplatform.generated.client";

    /** Returns a map of path (relative to the Java source root) to file content: the model
     * class and the client class for the given type. */
    public Map<String, String> emit(TypeDecl type) {
        Map<String, String> files = new LinkedHashMap<>();
        files.put("com/manas/metaplatform/generated/model/" + type.name() + ".java", emitModel(type));
        files.put("com/manas/metaplatform/generated/client/" + type.name() + "Client.java", emitClient(type));
        return files;
    }

    private String emitModel(TypeDecl type) {
        StringBuilder sb = new StringBuilder();
        sb.append("// GENERATED by com.manas.metaplatform.typesystem.compiler.JavaClientEmitter\n");
        sb.append("// from the single declaration of type ").append(type.name())
                .append(" in src/main/resources/typesystem/declared-types.dsl. Do not edit by hand.\n");
        sb.append("package ").append(MODEL_PACKAGE).append(";\n\n");
        sb.append("public class ").append(type.name()).append(" {\n\n");
        sb.append("    private Long id;\n");
        for (FieldDecl field : type.fields()) {
            sb.append("    private ").append(javaType(field)).append(" ").append(field.name()).append(";\n");
        }
        sb.append("\n    public ").append(type.name()).append("() {\n    }\n\n");
        sb.append("    public Long getId() {\n        return id;\n    }\n\n");
        sb.append("    public void setId(Long id) {\n        this.id = id;\n    }\n\n");
        for (FieldDecl field : type.fields()) {
            String javaType = javaType(field);
            String cap = capitalize(field.name());
            sb.append("    public ").append(javaType).append(" get").append(cap).append("() {\n")
                    .append("        return ").append(field.name()).append(";\n    }\n\n");
            sb.append("    public void set").append(cap).append("(").append(javaType).append(" ")
                    .append(field.name()).append(") {\n")
                    .append("        this.").append(field.name()).append(" = ").append(field.name())
                    .append(";\n    }\n\n");
        }
        sb.append("}\n");
        return sb.toString();
    }

    private String emitClient(TypeDecl type) {
        String name = type.name();
        StringBuilder sb = new StringBuilder();
        sb.append("// GENERATED by com.manas.metaplatform.typesystem.compiler.JavaClientEmitter\n");
        sb.append("// from the single declaration of type ").append(name)
                .append(" in src/main/resources/typesystem/declared-types.dsl. Do not edit by hand.\n");
        sb.append("package ").append(CLIENT_PACKAGE).append(";\n\n");
        sb.append("import ").append(MODEL_PACKAGE).append(".").append(name).append(";\n");
        sb.append("import com.manas.metaplatform.typesystem.client.GeneratedTypeClient;\n");
        sb.append("import com.manas.metaplatform.typesystem.client.TypeClientSupport;\n\n");
        sb.append("import java.util.List;\n");
        sb.append("import java.util.Map;\n");
        sb.append("import java.util.stream.Collectors;\n\n");
        sb.append("public class ").append(name).append("Client implements GeneratedTypeClient {\n\n");
        sb.append("    private final TypeClientSupport support;\n\n");
        sb.append("    public ").append(name).append("Client(String baseUrl) {\n");
        sb.append("        this.support = new TypeClientSupport(baseUrl);\n    }\n\n");
        sb.append("    @Override\n    public String typeName() {\n        return \"").append(name)
                .append("\";\n    }\n\n");
        sb.append("    public ").append(name).append(" createTyped(").append(name).append(" body) {\n");
        sb.append("        return support.postForObject(\"/api/types/").append(name)
                .append("\", body, ").append(name).append(".class);\n    }\n\n");
        sb.append("    public ").append(name).append(" getTyped(long id) {\n");
        sb.append("        return support.getForObject(\"/api/types/").append(name)
                .append("/\" + id, ").append(name).append(".class);\n    }\n\n");
        sb.append("    public List<").append(name).append("> listTyped(Map<String, Object> filters) {\n");
        sb.append("        ").append(name).append("[] rows = support.getForArray(\"/api/types/").append(name)
                .append("\" + support.buildFilterQueryString(filters), ").append(name).append("[].class);\n");
        sb.append("        return List.of(rows);\n    }\n\n");
        sb.append("    @Override\n    public Map<String, Object> create(Map<String, Object> fields) {\n");
        sb.append("        ").append(name).append(" body = support.mapper().convertValue(fields, ")
                .append(name).append(".class);\n");
        sb.append("        return support.toMap(createTyped(body));\n    }\n\n");
        sb.append("    @Override\n    public Map<String, Object> getById(long id) {\n");
        sb.append("        return support.toMap(getTyped(id));\n    }\n\n");
        sb.append("    @Override\n    public List<Map<String, Object>> list(Map<String, Object> equalityFilters) {\n");
        sb.append("        return listTyped(equalityFilters).stream().map(support::toMap)")
                .append(".collect(Collectors.toList());\n    }\n");
        sb.append("}\n");
        return sb.toString();
    }

    private String javaType(FieldDecl field) {
        return switch (field.type()) {
            case STRING -> "String";
            case NUMBER -> "Double";
            case BOOLEAN -> "Boolean";
        };
    }

    private String capitalize(String s) {
        return s.substring(0, 1).toUpperCase(Locale.ROOT) + s.substring(1);
    }
}
